properties.expression:
// Bounce on paths v1.0 - Makes a sin based bounce on point and tangets paths
const amp = 4;
const freq = 2;
const decay = 6;
let n = 0;
let ogPath = thisProperty; 
let ogPoints = ogPath.points(); 
let ogInTang = ogPath.inTangents(); 
let ogOutTang = ogPath.outTangents(); 
if (numKeys > 0) 
{
    n = nearestKey(time).index;
    (key(n).time > time) ? n-- : n = n;
}
(n == 0) ? t = 0 : t = time - key(n).time;
if (n > 0)
{   
    const timeFrame = thisComp.frameDuration*0.1;
    const timeInKeyframe = key(n).time;
    const timeDiference = timeInKeyframe - timeFrame;

    for(i = 0; i < ogPoints.length; i++)
    {   
        vx = (ogPath.points(timeInKeyframe)[i][0] - ogPath.points(timeDiference)[i][0]);
        vy = (ogPath.points(timeInKeyframe)[i][1]  - ogPath.points(timeDiference)[i][1]);

        ogPoints[i][0] = ogPoints[i][0] + bounce(vx/timeFrame);
        ogPoints[i][1] = ogPoints[i][1] + bounce(vy/timeFrame);

    }

    function bounce(vel)
    {
        return (vel*0.01)*amp*(Math.sin(2*Math.PI*freq*t)/Math.exp(decay*t));
    }
}
createPath(ogPoints,ogInTang,ogOutTang,ogPath.isClosed());

